// static
bool UnionTraits<::blink::mojom::WebPrintResult::DataView, ::blink::mojom::WebPrintResultPtr>::Read(
    ::blink::mojom::WebPrintResult::DataView input,
    ::blink::mojom::WebPrintResultPtr* output) {
  using UnionType = ::blink::mojom::WebPrintResult;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kPrintJobInfo: {
      ::blink::mojom::WebPrintJobInfoPtr result_print_job_info;
      if (!input.ReadPrintJobInfo(&result_print_job_info))
        return false;

      *output = UnionType::NewPrintJobInfo(
          std::move(result_print_job_info));
      break;
    }
    case Tag::kError: {
      ::blink::mojom::WebPrintError result_error;
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(result_error);
      break;
    }
    default:

      return false;
  }
  return true;
}

